});
const mainSphere = new THREE.Mesh(sphereGeometry, sphereMaterial);
mainSphere.castShadow = true;
mainSphere.receiveShadow = true;
heroGroup.add(mainSphere);

const goldMaterial = new THREE.MeshPhysicalMaterial({
  color: 0xffd700,
  metalness: 1.0,
  roughness: 0.15,
  clearcoat: 1.0,
  emissive: 0xffaa00,
  emissiveIntensity: 0.15
});

const wireframeGeometry = new THREE.IcosahedronGeometry(1.82, 2);
const wireframe = new THREE.LineSegments(
  new THREE.EdgesGeometry(wireframeGeometry),
  new THREE.LineBasicMaterial({ color: 0xffd700, linewidth: 2, opacity: 0.8, transparent: true })
);
heroGroup.add(wireframe);

const ringGeometry = new THREE.TorusGeometry(2.4, 0.04, 16, 128);
