ring1.rotation.x = Math.PI / 2;
heroGroup.add(ring1);

const ring2 = new THREE.Mesh(ringGeometry, goldMaterial);
ring2.rotation.y = Math.PI / 3;
ring2.scale.set(1.15, 1.15, 1.15);
heroGroup.add(ring2);

const ring3 = new THREE.Mesh(ringGeometry, goldMaterial);
ring3.rotation.x = Math.PI / 4;
ring3.rotation.z = Math.PI / 6;
ring3.scale.set(1.3, 1.3, 1.3);
heroGroup.add(ring3);

const outerWire = new THREE.LineSegments(
  new THREE.EdgesGeometry(new THREE.IcosahedronGeometry(2.8, 1)),
  new THREE.LineBasicMaterial({ color: 0xffd700, transparent: true, opacity: 0.3 })
);
heroGroup.add(outerWire);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.minDistance = 4;
controls.maxDistance = 12;
controls.target.set(0, 0, 0);

camera.position.set(5.5, 3.2, 6.8);

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  heroGroup.rotation.y = t * 0.12;
  heroGroup.rotation.x = Math.sin(t * 0.08) * 0.05;

  ring1.rotation.x = Math.PI / 2 + t * 0.15;
  ring1.rotation.y = Math.sin(t * 0.1) * 0.2;

  ring2.rotation.y = Math.PI / 3 + t * 0.12;
  ring2.rotation.z = Math.cos(t * 0.08) * 0.15;

  ring3.rotation.x = Math.PI / 4 + Math.sin(t * 0.09) * 0.1;
  ring3.rotation.z = Math.PI / 6 + t * 0.11;

  wireframe.rotation.y = -t * 0.05;
  outerWire.rotation.y = t * 0.03;
  outerWire.rotation.z = Math.sin(t * 0.04) * 0.1;

  rimLight.intensity = 0.75 + Math.sin(t * 1.5) * 0.15;
  rimLight.position.x = Math.sin(t * 0.5) * 2;

  controls.update();
  renderer.render(scene, camera);
}
