const particleCount = 200;
const particleGeo = new THREE.BufferGeometry();
const positions = new Float32Array(particleCount * 3);
const phases = new Float32Array(particleCount);

for (let i = 0; i < particleCount; i++) {
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.acos(2 * Math.random() - 1);
  const r = 4 + Math.random() * 4;
  positions[i * 3] = r * Math.sin(phi) * Math.cos(theta);
  positions[i * 3 + 1] = r * Math.sin(phi) * Math.sin(theta);
  positions[i * 3 + 2] = r * Math.cos(phi);
  phases[i] = Math.random() * Math.PI * 2;
}

particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
particleGeo.setAttribute('phase', new THREE.BufferAttribute(phases, 1));

const particleMat = new THREE.PointsMaterial({
  color: 0xaad6ff,
  size: 0.05,
  transparent: true,
  opacity: 0.6,
  blending: THREE.AdditiveBlending
});
const particles = new THREE.Points(particleGeo, particleMat);
heroGroup.add(particles);

camera.position.set(4.4, 2.4, 5.2);
camera.lookAt(0, 0, 0);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.autoRotate = true;
controls.autoRotateSpeed = 0.5;

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  core.rotation.y = t * 0.2;
  core.rotation.z = Math.sin(t * 0.1) * 0.1;

  ring1.rotation.z = t * 0.3;
  ring1.rotation.x = (Math.PI / 2) + Math.sin(t * 0.2) * 0.1;

  ring2.rotation.z = -t * 0.25;
  ring2.rotation.x = (Math.PI / 3) + Math.cos(t * 0.15) * 0.1;

  satellites.forEach((sat, i) => {
    const data = sat.userData;
    const angle = data.angle + t * data.speed * 0.5;
    sat.position.x = Math.cos(angle) * data.radius;
    sat.position.z = Math.sin(angle) * data.radius;
    sat.position.y = data.yOffset + Math.sin(t * 2 + i) * 0.3;
    sat.rotation.x = t * 0.5;
    sat.rotation.y = t * 0.3;
  });

  const posAttribute = particleGeo.attributes.position;
  const phaseAttribute = particleGeo.attributes.phase;
  for (let i = 0; i < particleCount; i++) {
    const phase = phaseAttribute.getX(i);
    const y = posAttribute.getY(i);
    posAttribute.setY(i, y + Math.sin(t + phase) * 0.002);
  }
  posAttribute.needsUpdate = true;
  particles.rotation.y = t * 0.05;

  rimLight.intensity = 0.35 + Math.sin(t * 1.2) * 0.08;
  fillLight.intensity = 0.55 + Math.cos(t * 0.8) * 0.05;

  heroGroup.position.y = Math.sin(t * 0.5) * 0.2;

  controls.update();
  renderer.render(scene, camera);
}
animate();

