  const phi = Math.acos(2 * Math.random() - 1);
  const r = 4 + Math.random() * 3;

  mesh.position.set(
    r * Math.sin(phi) * Math.cos(theta),
    r * Math.sin(phi) * Math.sin(theta),
    r * Math.cos(phi)
  );

  mesh.userData = {
    velocity: new THREE.Vector3(
      (Math.random() - 0.5) * 0.01,
      (Math.random() - 0.5) * 0.01,
      (Math.random() - 0.5) * 0.01
    ),
    phase: Math.random() * Math.PI * 2
  };

  particles.add(mesh);
}
