controls.minDistance = 4;
controls.maxDistance = 15;
controls.maxPolarAngle = Math.PI / 2 - 0.05;

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();
  const delta = clock.getDelta();

  innerCore.rotation.x = t * 0.15;
  innerCore.rotation.y = t * 0.25;

  outerRing.rotation.x = t * 0.1 + Math.sin(t * 0.3) * 0.2;
  outerRing.rotation.y = t * 0.2;
  outerRing.rotation.z = Math.sin(t * 0.15) * 0.1;

  heroGroup.position.y = Math.sin(t * 0.5) * 0.3;

  satellites.forEach((sat, i) => {
    const data = sat.userData;
    const angle = data.baseAngle + t * data.speed * 0.3;
    sat.position.x = Math.cos(angle) * data.radius;
    sat.position.z = Math.sin(angle) * data.radius;
    sat.position.y = data.yOffset + Math.sin(t * 1.5 + i) * 0.4;
    sat.rotation.x = t * 0.5;
    sat.rotation.y = t * 0.3;
  });

  particles.children.forEach((p, i) => {
    p.position.add(p.userData.velocity);
    p.position.y += Math.sin(t * 2 + p.userData.phase) * 0.002;

    const dist = p.position.length();
    if (dist > 8 || dist < 3) {
      p.userData.velocity.multiplyScalar(-1);
    }

    const scale = 0.8 + Math.sin(t * 3 + p.userData.phase) * 0.4;
    p.scale.setScalar(scale);
  });

  heroGroup.rotation.y = t * 0.08;

  rimLight.intensity = 0.45 + Math.sin(t * 1.2) * 0.15;
  fillLight.intensity = 0.55 + Math.cos(t * 0.7) * 0.1;

  controls.update();
  renderer.render(scene, camera);
}

